// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(bytes32 assertionId) public {
        // Call assertionDisputedCallback as the optimistic asserter (this contract)
        // The reference should succeed; the buggy version should revert
        (bool success, ) = address(c).call(abi.encodeWithSignature("assertionDisputedCallback(bytes32)", assertionId));
        assertTrue(success);
    }
}

